def boundary_composition(self, t):
        """Prescribed reservoir on the thermal-stage clock, independent of pore state.

        Linear interpolation preserves positive, normalized mole fractions.
        Initial pore inventory is unchanged; only boundary exchange changes.
        """
        return np.array([np.interp(t,self.times,self.gas_knots[:,i]) for i in range(self.g)])

def caloric_capacity(self,T,ns,ng):
        capacity=ns@self.cp[:len(self.ns)]+np.sum(ng*(self.gas_molar_cp(T)-self.R),axis=1)
        if self.water_cp_slope != 0:
            capacity+=ns[:,self.water_index]*self.water_cp_slope*(T-self.Tr)
        if self.retention_scale_value != 0:
            water=ns[:,self.water_index]
            sites=self.retention_matrix*self.site_survival+self.site_slope*ns[:,self.kaolin]
            capacity+=self.binding_cp*water*sites/(water+sites)
        return capacity

def carbonate_phase_mobility(self, ns):
        """Assumed common kinetic multiplier for the reversible carbonate pool."""
        if self.carbonate_phase_resistance == 0:
            return np.ones_like(ns[:,self.lime])
        return 1/(1+self.carbonate_phase_resistance*ns[:,self.lime]/self.calcium_pool)

def condensed_state(self, fields):
        ns = super().condensed_state(fields)
        ns[:,self.portlandite] = self.chemical_scale*fields[self.hydroxide_coordinate]
        if self.calcium_coordinate_mode == 1:
            # Same conserved-Ca manifold; encode a declared zero CaO directly.
            # Calcite remainder and all raw floating-point excursions are retained.
            ns[:,self.lime] = self.calcium_pool*fields[3]
            ns[:,self.calcite] = self.calcium_pool-ns[:,self.lime]-ns[:,self.portlandite]
        else:
            if self.calcium_fraction_coordinate:
                ns[:,self.calcite] = self.calcium_pool*fields[3]
            ns[:,self.lime] = self.calcium_pool-ns[:,self.calcite]-ns[:,self.portlandite]
        return ns

def gas_knudsen_diffusivity(self, thermal_mean, pore_length, phi, tortuosity):
        """Published cylindrical-pore coefficient with assumed diameter proxy."""
        face_phi = np.r_[(phi[:-1]+phi[1:])/2, phi[-1]]
        return (face_phi/tortuosity*pore_length*self.knudsen_prefactor)[:,None]*np.sqrt(
            self.R*thermal_mean[:,None]/self.mw[len(self.ns):][None,:])

def gas_state(self, y, temperature, pore):
        inventory = self.initial_gas * np.exp(y[self.gas_offset:self.extent_offset].reshape(self.g, self.n).T)
        partial = inventory*self.R*temperature[:, None]/pore[:, None]
        return inventory, partial, partial.sum(axis=1)

def retention_sites(self, fields):
        """Immobile equivalents: persistent sites plus kaolin-carried sites.

        N=N0*(r+(1-r)*n_kaolin/n_kaolin_initial), with declared positive r.
        Sites add no mass or state; their composition derivative is site_slope.
        """
        return self.retention_matrix*(self.site_survival+(1-self.site_survival)*np.exp(-fields[2]))

def water_mobility_resistance(self, T):
        """D_ref/D(T) for the declared reference-anchored Arrhenius law."""
        return np.exp(self.water_mobility_activation/self.R*(1/T-1/self.Tr))

def center_temperature(self, temperature):
        """Symmetric quadratic diagnostic in the initial material coordinate."""
        if not self.cellwise_partition:
            return float((9*temperature[0]-temperature[1])/8)
        x = self.initial_partition['centers_m'][:2]
        return float((x[1]**2*temperature[0]-x[0]**2*temperature[1])/(x[1]**2-x[0]**2))

def heat_transfer(self, T, ns, bulk, tf):
        conductivity = self.effective_conductivity(ns, bulk)+self.pore_radiative_conductivity(T, ns, bulk)
        return self.heat_transfer_from_conductivity(T, bulk, tf, conductivity)

def p(self, key: str, unit: str):
        item = self.config["parameters"][key]
        if item["unit"] != unit:
            raise ValueError(f"dimension mismatch for {key}: expected {unit}, found {item['unit']}")
        self.used_units[key] = unit
        return item["value"]

def dry_temperature_conductivity_factor(self,T):
        """Assumed dry-skeleton transport factor on a finite positive-T domain."""
        if self.dry_conductivity_temperature_exponent == 0:
            return np.ones_like(T)
        return (T/self.Tr)**self.dry_conductivity_temperature_exponent

def elastic_strain(self,f,T,bulk,ns=None):
        strain=bulk/self.b0-1-self.thermal_strain(T)[0]-f[6]+self.initial_elastic_strain
        if self.liquid_strain != 0 and self.liquid_active != 0:
            if ns is None:
                ns=self.condensed_state(f)
            strain=strain-self.phase_eigenstrain(f,ns)[0]
        return strain

def liquid_coordinate_rate(self,T,fields,elastic_affinity):
        rate=np.exp(-self.liquid_activation/self.R*(1/T-1/self.liquid_tc))/self.liquid_tau
        return -rate*self.liquid_driving_log_odds(T,fields,elastic_affinity)

def liquid_driving_log_odds(self,T,fields,elastic_affinity):
        drive=fields[self.liquid_coordinate]-self.liquid_equilibrium_log_odds(T)
        if self.liquid_strain != 0 or self.phase_modulus_contrast != 0:
            drive=drive+elastic_affinity/(self.liquid_mixing*T)
        return drive

def liquid_equilibrium_log_odds(self,T):
        if self.liquid_cp == 0:
            return self.liquid_latent/self.liquid_mixing*(1/self.liquid_tc-1/T)
        enthalpy,entropy=self.liquid_contrast(T)
        return (entropy-enthalpy/T)/self.liquid_mixing

def liquid_state(self,T,ns,fields):
        x=self.liquid_order(fields[self.liquid_coordinate])[0] if self.kinetic_liquid else self.liquid_phase(T)[0]
        liquid_moles=self.liquid_active*ns[:,self.matrix]*x
        dry_volume=ns@self.v-ns[:,self.water_index]*self.v[self.water_index]
        fraction=liquid_moles*self.v[self.matrix]/dry_volume
        return liquid_moles,fraction,np.exp(self.liquid_gain*fraction)

def native_potential_state(self, y):
        """Decode one real native state; volume stays explicit in the chart."""
        f,T,ns,bulk,pore,surface,cap=self.unpack(y)
        gas_log=y[self.gas_offset:self.extent_offset].reshape(self.g,self.n)
        return self._potential_state_from_decoded(y,f,T,ns,self.initial_gas*np.exp(gas_log.T),
            bulk,pore,surface,completed_native_unpack_calls=1)

def skeleton_chemical_potential(self,fields,T,ns,bulk):
        if self.modulus_exponent == 0 and self.liquid_strain == 0 and self.phase_modulus_contrast == 0:
            return super().skeleton_chemical_potential(fields,T,ns,bulk)
        elastic=self.elastic_response(fields,T,ns,bulk)
        potential=elastic['free_dry_derivative'][:,None]*self.dry_v
        birth=self.phase_eigenstrain(fields,ns)[1]
        potential[:,self.matrix]-=self.b0*elastic['modulus']*elastic['eps']*birth
        if self.phase_modulus_contrast != 0:
            phase_birth=self.phase_reference_volume(fields,ns)[1]
            potential[:,self.matrix]-=self.b0*self.phase_modulus_contrast*elastic['modulus']*elastic['eps']**2/2*phase_birth
        return potential

def state_caloric_capacity(self,T,ns,ng,fields):
        cpq,_,_=self.quartz_thermo(T)
        capacity=super().caloric_capacity(T,ns,ng)+ns[:,self.quartz]*(cpq-self.cp[self.quartz])
        if np.any(self.dry_cp_slope != 0):
            capacity+=np.sum(ns[:,self.linear_dry_indices]*(T[:,None]-self.Tr)*self.dry_cp_slope,axis=1)
        mineral_cp=source_caloric_integrals(T,self.mineral_caloric_coefficients,self.Tr)[0]
        capacity+=np.sum(ns[:,self.mineral_caloric_indices]*(mineral_cp-self.cp[self.mineral_caloric_indices]),axis=1)
        if not self.kinetic_liquid:
            capacity+=ns[:,self.matrix]*self.liquid_active*self.liquid_phase(T)[2]
        elif self.liquid_cp != 0:
            capacity+=ns[:,self.matrix]*self.liquid_active*self.liquid_order(fields[self.liquid_coordinate])[0]*self.liquid_cp
        return capacity

def state_heat_transfer(self,T,ns,bulk,tf,fields):
        if self.phase_conductivity_contrast == 0 and self.dry_conductivity_temperature_exponent == 0:
            return super().state_heat_transfer(T,ns,bulk,tf,fields)
        background,_=self.phase_conductivity(T,ns,bulk,fields)
        conductivity=background+self.pore_radiative_conductivity(T,ns,bulk)
        return self.heat_transfer_from_conductivity(T,bulk,tf,conductivity)

def _source_text(config):
    root = Path(__file__).resolve().parents[3]
    return {name: (root/name).read_text()
            for name in config['native_checkpoint']['source_paths']}

def configured_sampler(model):
    contract = model.config['face_energy_sampling']
    mode = model.p(contract['enabled_parameter'], '1')
    if mode == 0:
        return None
    if mode != 1:
        raise ValueError('face-energy sampling explicitly selects 0 or 1')
    return FaceEnergySamples(model, contract)

def initial_partition(*, cells: int, half_thickness_m: float, area_m2: float,
                      profile: str, exterior_exponent: float) -> dict:
    """Return reference faces/centers/widths (m) and cell volumes (m3).

    The exponent is an explicit numerical input, including for the uniform
    profile. No profile is selected implicitly. Interior distances are the
    sum of adjacent half widths; exterior distance is the last half width.
    """
    if not isinstance(cells, int) or isinstance(cells, bool) or cells <= 0:
        raise ValueError('cells must be a positive integer')
    if not np.isfinite([half_thickness_m, area_m2, exterior_exponent]).all() or min(half_thickness_m, area_m2, exterior_exponent) <= 0:
        raise ValueError('length, area and exponent must be finite and positive')
    coordinate = np.arange(cells + 1, dtype=float) / cells
    if profile == 'uniform':
        faces = half_thickness_m * coordinate
    elif profile == 'exterior_power':
        faces = half_thickness_m * (1 - (1 - coordinate) ** exterior_exponent)
    else:
        raise ValueError('profile must be uniform or exterior_power')
    # Uniform widths retain the original constant L/N representation.
    widths = np.full(cells, half_thickness_m / cells) if profile == 'uniform' else np.diff(faces)
    if np.any(widths <= 0):
        raise ValueError('profile must yield strictly increasing faces')
    centers = (faces[:-1] + faces[1:]) / 2
    bulk = np.full(cells, area_m2 * half_thickness_m / cells) if profile == 'uniform' else area_m2 * widths
    return {'faces_m': faces, 'centers_m': centers, 'widths_m': widths,
            'initial_bulk_m3': bulk,
            'internal_center_distance_m': np.diff(centers),
            'symmetry_half_width_m': widths[0] / 2,
            'exterior_half_width_m': widths[-1] / 2}

def initial_partition_from_faces(*, faces_m, cells: int,
                                 half_thickness_m: float, area_m2: float) -> dict:
    """Use explicit initial reference faces without resampling or snapping.

    Bulk volumes use area times face differences; saved fine-volume sums
    are a separate basis and are not substituted here.
    """
    faces = np.asarray(faces_m, dtype=float)
    if not isinstance(cells, int) or isinstance(cells, bool) or cells <= 0:
        raise ValueError('cells must be a positive integer')
    if faces.ndim != 1 or faces.size != cells + 1:
        raise ValueError('explicit faces must contain cells+1 positions')
    if not np.isfinite([half_thickness_m, area_m2]).all() or min(half_thickness_m, area_m2) <= 0:
        raise ValueError('length and area must be finite and positive')
    if faces[0] != 0 or faces[-1] != half_thickness_m:
        raise ValueError('explicit faces must start at zero and end at the supplied half thickness')
    widths = np.diff(faces)
    if not np.all(widths > 0):
        raise ValueError('explicit faces must be strictly increasing')
    centers = (faces[:-1] + faces[1:]) / 2
    return {'faces_m': faces, 'centers_m': centers, 'widths_m': widths,
            'initial_bulk_m3': area_m2 * widths,
            'internal_center_distance_m': np.diff(centers),
            'symmetry_half_width_m': widths[0] / 2,
            'exterior_half_width_m': widths[-1] / 2}

def make_cycle(config: dict):
    mode = config['parameters']['gas.storage']['value']
    if mode == 0:
        if config['parameters'][config['face_energy_sampling']['enabled_parameter']]['value'] != 0:
            raise ValueError('face-energy sampling requires finite stored pore gas: gas.storage=1')
        if 'direct_carbonation' in config:
            raise ValueError('direct_carbonation requires finite stored pore gas: gas.storage=1')
        return FullCycle(config)
    if mode == 1 and config['parameters']['solid.thermoelastic']['value'] == 1:
        from .full_cycle_solid import ThermoelasticFullCycle
        return ThermoelasticFullCycle(config)
    if mode == 1 and config['parameters']['solid.thermoelastic']['value'] == 0:
        from .full_cycle_gas import FiniteGasFullCycle
        return FiniteGasFullCycle(config)
    raise ValueError('gas.storage and solid.thermoelastic must explicitly select 0 or 1')

def parse_formula(formula: str | Mapping[str, float]) -> dict[str, float]:
    if isinstance(formula, Mapping):
        parsed = {str(element): float(count) for element, count in formula.items()}
    elif isinstance(formula, str):
        parsed: dict[str, float] = {}
        position = 0
        for match in _TOKEN.finditer(formula):
            if match.start() != position:
                raise ValueError(f"unsupported formula syntax at position {position}: {formula!r}")
            element, count_text = match.groups()
            parsed[element] = parsed.get(element, 0.0) + (float(count_text) if count_text else 1.0)
            position = match.end()
        if position != len(formula) or not parsed:
            raise ValueError(f"unsupported formula: {formula!r}")
    else:
        raise TypeError("formula must be a string or element-count mapping")
    if any(count <= 0.0 for count in parsed.values()):
        raise ValueError("formula counts must be positive")
    return parsed

def relative_residual(residual, scale, *, unit, source, threshold):
    """A zero actual denominator has no relative verdict, even at zero residual."""
    defined = scale != 0
    relative = abs(residual)/abs(scale) if defined else None
    return {'signed_residual':float(residual), 'unit':unit,
            'denominator':float(scale), 'denominator_source':source,
            'absolute_relative_residual':float(relative) if defined else None,
            'denominator_status':'defined' if defined else 'undefined_zero_budget',
            'passed':bool(relative < threshold) if defined and threshold is not None else (None if defined else False),
            'threshold':threshold}

def source_caloric_coefficients(model, names):
    units = ('J/mol/K', 'J/mol/K2', 'J*K/mol', 'J/mol/K0.5', 'J/mol/K3')
    return np.array([[model.p('species.'+name+'.caloric_A'+str(j), unit)
                      for j, unit in enumerate(units, 1)] for name in names])
